 import pandas as pd;d=pd.DataFrame(r);g=d.groupby(['compound','food_matrix','cooking_method_normalized','measurement_basis']).agg(observations=('observation_id','size'),source_families=('doi','nunique'),sources=('doi',lambda z:';'.join(sorted(set(z))))).reset_index();g.to_csv(P/'exact_matched_cell_matrix.csv',index=False);g[g.source_families>=2].to_csv(P/'multi_source_exact_cells.csv',index=False)
 (P/'candidate_b_extraction_report.md').write_text('# Candidate B extraction\n\nMusilova et al. (2020), DOI `10.1155/2020/8856260`, Table 6 reports HPLC-DAD chlorogenic, neochlorogenic, and trans-ferulic acid in mg/kg FW. Methods: 3-mm peeled sweet-potato slices; boiling 10 min, steaming 15 min at 97 ± 2 C, microwave 5 min/800 W, baking 15 min/200 C. Four cultivar-origin strata, quadruplicate means.\n\nAdmitted: 32 directly comparable apparent-ratio pairs for chlorogenic and trans-ferulic acids. Neochlorogenic acid: excluded from model-ready data because no verified canonical molecular descriptor record exists in the established schema; values are not discarded from the audit.\n',encoding='utf-8');(P/'exclusion_log.csv').write_text('candidate,status,reason\nNeochlorogenic acid,EXCLUDED_SCHEMA_GAP,No verified existing canonical molecular descriptor record; no descriptor was invented.\n',encoding='utf-8');(P/'modelling_readiness.md').write_text('# Readiness\n\nDecision C: continue targeted matched-evidence acquisition. The 32 Candidate-B observations diversify compounds and protocols but do not add a third independent source to any existing exact vitamin-C carrot/spinach cell. No new generalisation model is justified.\n',encoding='utf-8');(P/'iteration_summary.md').write_text(f'v0.8: {len(r)} rows; {d.doi.nunique()} DOI families; 32 new verified observations; Stage C unchanged.\n',encoding='utf-8');m={'rows':len(r),'sources':d.doi.nunique(),'new_rows':32,'parent_sha256':sha(OLD),'stage_c_integration_authorized':False};(P/'manifest.json').write_text(json.dumps(m,indent=2)+'\n');files=[q for q in P.rglob('*') if q.is_file() and q.name!='SHA256SUMS.txt'];(P/'SHA256SUMS.txt').write_text(''.join(f'{sha(q)}  {q.relative_to(P)}\n' for q in sorted(files)))
